Record cs_ok (E : env) (cs : acs) (R : bvmap 5 word) (FULL : word -> option byte) (model : Model) : Prop := CS_OK {
  (* [comment removed for export] *)
  co_regs  : regs_ok E (s_regs (a_ss cs)) R;
  co_log   : s_log (a_ss cs) = [];
  co_know  : know_ok SEGS E (Mr E cs model FULL) (kn cs);
  (* [comment removed for export] *)
  co_halt  : m_halted model = None;
  co_fds   : fds_ok E (a_fd cs) model;
  co_fs    : m_fs model = FS0;
  co_tid   : a_tidset cs = false -> m_tid model = None;
  (** 75d69e00: the reserved ledger is the image's reservations AND THE vDSO PAIR.
      OLD, and false at init at this revision:
        co_res : vm_reserved (m_vmmaps model) = segments_reserved SEGS
      [State.init_model]'s ledger is [reserved ++ vdso_reserved (in_kernel inp) (vdso_top …)]
      ([State.vm_reserved_init_model], 75d69e00:theories/LinuxProcessSem/State.v:7844, and
      [vdso_top_init_model] at :7835 -- both in the SHIPPED LinuxProcessSem, so neither is a
      theories/Common port), so the plain equality cannot be proved of the start state by any
      repair above it.  Same model change that makes KLB false at init in the other spine.
      The new form is the model's OWN shape rather than a second equality, and the kernel
      build is EXISTENTIAL: [vdso_reserved] reads [kb_vdso_pages]/[kb_vvar_pages] off it, and
      [Run.valid_input] leaves the build free, so pinning it here would pin kb_rseq's record
      by the back door.  [vdso_top] is the model's own, so nothing new is threaded in. *)
  (* LPS 727298f3 port: the mmap-base bound is a conjunct of [co_res] again (see the note
     below [co_wf]).  [slice_cs1_ok], the recorded builder that broke on the first fold,
     is written out now, so the record's arity stays 30 and its type is built in text.
     The third conjunct says every tracked mapping is apart from the whole ledger.  The
     ledger now holds the vDSO/vvar pair, which lies below [vdso_top] in the same band as
     the mappings, so a range inside a mapping is free of the ledger only by this fact
     (the same conjunct as bzip2's ported [co_res]).  Every grant gets it from the
     [region_free] over the ledger and the mappings that the grant already checks. *)
  co_res   : exists kb, vm_reserved (m_vmmaps model)
                        = segments_reserved SEGS ++ vdso_reserved kb (vdso_top (m_vmmaps model))
                     /\ mmap_base_min <= bv_unsigned (vm_mmap_base (m_vmmaps model))
                     /\ Forall (fun iv => Forall (iv_disjoint iv) (vm_reserved (m_vmmaps model)))
                               (vm_maps (m_vmmaps model))
                     (* the launch's vDSO/vvar pair is in the ledger: what the revision's
                        mprotect gate needs, as bzip2's ported [co_res] carries it *)
                     /\ incl (vdso_reserved (m_kernel model) (vdso_top (m_vmmaps model)))
                             (vm_reserved (m_vmmaps model));
  co_limit : vm_limit (m_vmmaps model) = LIMIT;
  (* [comment removed for export] *)
  co_maps  : maps_match E (a_maps cs) (vm_maps (m_vmmaps model));
  co_holes : Forall (hole_ok E (a_ylo cs) (vm_reserved (m_vmmaps model) ++ vm_maps (m_vmmaps model))) (a_maps cs);   (* [comment removed for export] *)
  co_seps  : seps (vm_maps (m_vmmaps model));
  co_wf    : model_ivs_wf model;
  (** 2026-11-07: [co_mbase : mmap_base_min <= bv_unsigned (vm_mmap_base (m_vmmaps model))]
      WAS A FIELD HERE and is REMOVED, restoring [cs_ok] to the 30 fields this unit's
      recorded proofs were built against.
      CAUSE, measured over two whole-unit rounds rather than argued.
        a farm round (31 fields) died at AsanNodesMmLib.v:1881 with
          Anomaly "decompose_lambda_n_decls: not enough declarations"
        and ABSENTED 118 files -- every StartupCert, the whole Main cone, all 11 Top/*
        and Theorems.v, every one of them behind that single error.
        a farm round folded the fact into [co_res] as a conjunct (30
        fields again) and the Anomaly became
          :1891 chars 30786-30790  Illegal application: The term "CS_OK" of type ...
      Those five characters are the TAIL of the 30,785-character blob at :1881, so that
      replay APPLIES [CS_OK] POSITIONALLY -- it BUILDS the record rather than matching it.
      A builder is broken by any change to the record's TYPE, not merely to its arity, so
      folding into an existing field does not help it either.  (Diagnostic worth keeping:
      Anomaly "decompose_lambda_n_decls" = a MATCHER, broken by arity; Illegal application
      naming the CONSTRUCTOR = a BUILDER, broken by type.)
      LPS 727298f3 port: the fact is folded into [co_res] as a conjunct again.  The one
      recorded builder the earlier fold broke, [slice_cs1_ok]'s blob at
      AsanNodesMmLib.v:1881, is written out now (in this unit's 75d69e00 port), and every
      other place that builds or opens [co_res] is plain text,
      so the premise that the 2026-11-07 repair threaded through
      [AsanNodesMmLib.reserved_free_above] and [region_free_of_apart] is gone: the launch
      proves it once ([AsanInit.init_cs_ok], from [mb_range]) and each step carries it.
      WHAT IT SAID, kept because the derivation is still live for that premise: [co_res]
      puts the reserved ledger at [segments_reserved SEGS ++ vdso_reserved kb (vdso_top
      (m_vmmaps model))], and [vdso_top h] is [page_round_down_Z (Z.min (bv_unsigned
      (vm_mmap_base h)) (page_round_down_Z (alloc_top h)))].  [co_wf]'s [init_sp_ok] pins
      the second half of that [Z.min]; NOTHING pins the first, which is why no existing
      field yields this and why it had to be stated somewhere.  [mmap_base_min =
      23387528589312] is well above [KHI = 0x10007fff8000 = 17596481536000], so the pair
      misses every range a shadow or image fact talks about.  True of the launch
      ([AsanInit]'s [vtop_range] bounds the same base) and preserved by every step, because
      each next-state rebuilds [mkVmMapsFull] with the model's own [vm_mmap_base]. *)
  co_bounds : Forall (fun iv => 0 < bv_unsigned (snd iv)
                                /\ bv_unsigned (fst iv) mod 4096 = 0 /\ bv_unsigned (snd iv) mod 4096 = 0
                                /\ (bv_unsigned (fst iv) + bv_unsigned (snd iv) <= img_lo A \/ img_hi A <= bv_unsigned (fst iv))
                                /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= TOP model) (vm_maps (m_vmmaps model));
  co_lazyb : Forall (fun iv => (bv_unsigned (fst iv) + bv_unsigned (snd iv) <= img_lo A \/ img_hi A <= bv_unsigned (fst iv))
                               /\ bv_unsigned (fst iv) + bv_unsigned (snd iv) <= TOP model) (m_vm_lazy model);
  (* [comment removed for export] *)
  co_top   : CEIL <= TOP model <= CEILMAX;
  co_sp0   : TOP model = bv_unsigned (edenot E e_sp0_early) - 8388608;
  co_nasub : forall z, in_ivs z (vm_noaccess (m_vmmaps model)) = true -> in_ivs z (vm_maps (m_vmmaps model)) = true;
  co_none  : Forall (fun m => am_kind m = KNONE \/ am_kind m = KNONELAZY ->
               In (amap_den E m) (vm_noaccess (m_vmmaps model))) (a_maps cs);
  co_kinds : Forall (fun m => am_kind m = KRWLAZY ->
               forall a : word, bv_unsigned (edenot E (am_base m)) <= bv_unsigned a < bv_unsigned (edenot E (am_base m)) + bv_unsigned (edenot E (am_len m)) ->
                 in_ivs (bv_unsigned a) (vm_noaccess (m_vmmaps model)) = false
                 /\ page_in_ranges (page_base a) (m_vm_lazy model) = true) (a_maps cs);
  co_totsz : sum_sizes (vm_reserved (m_vmmaps model) ++ vm_maps (m_vmmaps model)) <= a_totsz cs;
  (* [comment removed for export] *)
  co_brk   : vm_brk (m_vmmaps model) = edenot E (a_brk cs);
  co_sbrk  : bv_unsigned (vm_start_brk (m_vmmaps model)) <= bv_unsigned (vm_brk (m_vmmaps model));
  (* [comment removed for export] *)
  co_eager : eager_used model <= a_eager cs;
  co_abytes : A_bytes (allowA E cs) <= a_abytes cs;
  co_minv  : MInv (allowA E cs) model;
  (* [comment removed for export] *)
  co_zero  : forall a : word, hid E cs model a = true ->
               in_ivs (bv_unsigned a) (vm_maps (m_vmmaps model)) = true ->
               in_ivs (bv_unsigned a) (vm_noaccess (m_vmmaps model)) = false ->
               page_in_ranges (page_base a) (m_vm_lazy model) = true ->
               in_ghost E cs (bv_unsigned a) = false ->
               FULL a = Some (Z_to_bv 8 0);
  co_sinv  : SINV E FULL;
  (* [comment removed for export] *)
  co_vmx   : vm_noaccess (m_vmmaps model) = fst (vm_replay E (a_vmops cs)) /\ m_vm_lazy model = snd (vm_replay E (a_vmops cs));
  (* LPS 727298f3: the launch's channel reader ([Run.valid_input_channel_reader]); a write
     needs it.  No start-up step changes [m_proc], so every node keeps it. *)
  co_rdr   : m_channel_reader model = true
}.

