Lemma hid_same : ltac2:(zQ "90!jif!mj8!hs7!ho9!ma!om0!kud!ld!hqa>1E$7>2cs$6>5model$0>6model'$0>0@2$5^2^1@3$3>1a@1$8@1$4#k0$2@3$1^5^4^2@3$1^5^4^3").
