Lemma cs_ok_frame : ltac2:(zQ "ha1!ma!hqa!io1!ho9!jif!jle!oie!ona!hs7!hsf!kt4!nka!oo3!om0!kud!oob!op6!oh6!mj8!ld!opc!oq5!oqd!or6!pg9!ph4&>0@1$1@1$0#k0@1$2@1$1@1$0#8>1E$h3>2cs$e>1R@2$5@1$0#5@1$1@1$0#k0>4FULL~0>5model$4>3ss'$h7>2R'@2$5@1$0#5@1$1@1$0#k0>5FULL'~0>6model'$4>0@5$6^9^8^7^6^5>0@2$d^6^2>0@2$c@2$h1^b^a^3>0@3$h9^c@1$h6^7^6>0@3$3@1$9$7@1$h5^8@1$a$7>0@4$h8?4SEGS^e@4$h0^e^d^a^7@1$h4^9>0>1a@1$1@1$0#k0>0@3$3$8@4$h2^h0^f^c^1$b@3$3@1$2@1$1@1$0#8@1^a^2@1^e^2@5$6^h0@2$f^f^b^a^9^8").
Proof.
  intros E cs R FULL model ss' R' FULL' model' Hco Hsm Hinv Hregs Hlog Hknow Hfull.
  (* same_but_materialized model model' is
       model' = with_vm_backing (m_vm_lazy model) (m_vm_materialized model') model
     (75d69e00:theories/Common/AsanAcct.v:66), so it touches ONLY the lazy and
     materialized backings: every other projection is literally model's. *)
  unfold same_but_materialized in Hsm.
  assert (Hvm : m_vmmaps model' = m_vmmaps model)   by (rewrite Hsm at 1; reflexivity).
  assert (Hlz : m_vm_lazy model' = m_vm_lazy model) by (rewrite Hsm at 1; reflexivity).
  assert (Hht : m_halted model' = m_halted model)   by (rewrite Hsm at 1; reflexivity).
  assert (Hfd : m_fds model' = m_fds model)         by (rewrite Hsm at 1; reflexivity).
  assert (Hfs : m_fs model' = m_fs model)           by (rewrite Hsm at 1; reflexivity).
  assert (Htd : m_tid model' = m_tid model)         by (rewrite Hsm at 1; reflexivity).
  assert (Hrd : m_channel_reader model' = m_channel_reader model) by (rewrite Hsm at 1; reflexivity).
  assert (Htop : TOP model' = TOP model)            by (unfold TOP; rewrite Hvm; reflexivity).
  (* the probe named the three differences this has to close: TOP, the lazy backing and
     [in_allow] under [with_ss].  [with_ss] replaces only [a_ss], so [a_maps]/[a_ghost]/
     [a_ylo] -- all [in_allow] reads -- are [cs]'s. *)
  assert (Hhid : forall a, hid E (with_ss cs ss') model' a = hid E cs model a)
    by (intros a; unfold hid, vis, in_allow;
        cbn [with_ss a_ss a_ghost a_maps a_ylo];
        rewrite Hvm, Hlz, Htop; reflexivity).
  destruct Hco.
  constructor;
    cbn [with_ss a_ss a_fd a_maps a_ylo a_tidset a_brk a_totsz a_eager a_abytes];
    rewrite ?Hvm, ?Hlz, ?Hht, ?Hfd, ?Hfs, ?Htd, ?Htop, ?Hhid, ?Hrd;
    try assumption.
  (* co_know: the probe named this as the one field [assumption] cannot reach, because
     [Mr] is a FUNCTION of [hid] and the two sides differ inside it.  [functional_
     extensionality] is already in this tree's assumption set (AsanAcct.v uses it six
     times), so this adds no new axiom. *)
  all: try (cbn [kn with_ss a_ss];
            replace (Mr E (with_ss cs ss') model' FULL') with (Mr E cs model FULL');
            [ exact Hknow
            | unfold Mr, mrestrict; apply functional_extensionality; intros a;
              rewrite Hhid; reflexivity ]).
  (* First the generic model' -> model transport: rewriting Hsm turns every remaining
     `… model'` into `… (with_vm_backing (m_vm_lazy model) (m_vm_materialized model') model)`,
     whose projections reduce to model's for everything except the two backings. *)
  all: try (rewrite Hsm at 1;
            cbn [with_vm_backing m_fds m_fs m_halted m_tid m_vmmaps m_vm_lazy m_vm_materialized];
            assumption).
  (* The enumeration left exactly two of the twenty-nine, and both are about FULL'
     rather than about model': they are the two the frame's own hypothesis Hfull is for. *)
  (* co_zero *)
  all: try (intros a Ha Hm Hn Hp Hg;
            rewrite Hhid in Ha; cbn [with_ss a_ss] in Hg;
            rewrite (Hfull a Ha);
            (* wildcards, not E/cs/model: a `match goal` PATTERN is elaborated against the
               GLOBAL environment at parse time, so naming a local bound by this proof's
               own `intros` gives "The reference E was not found". *)
            match goal with
            | H : forall x : word, hid _ _ _ x = true -> _ |- _ => apply H; assumption
            end).
  (* co_sinv: SINV_frame is the Section's own hypothesis, instantiated in AsanInit by
     SINV0_frame.  argH a = true implies hid a = true, so Hfull covers its premise. *)
  (* applied WITHOUT naming its binders: the explicit form failed to elaborate ("the
     reference E was not found"), so SINV_frame's own argument order is not E M M'. *)
  all: try (eapply SINV_frame;
            [ intros a Ha; apply Hfull; unfold hid; rewrite Ha; reflexivity
            | eassumption ]).
  all: try (eapply SINV_frame; [ eassumption | intros a Ha; apply Hfull; unfold hid; rewrite Ha; reflexivity ]).
Qed.

