Lemma cs_ok_set_kn : ltac2:(zQ "d0!ma!hqa!oie!hsf!io1!jif!jle!kud!pj2!op6!ld!phf!pg9>1E$a>2cs$7>1R@2$6@1$0#5@1$1@1$0#k0>4FULL>0@1$1@1$0#k0@1$4@1$1@1$0#8>5model$5>2k'@1$3$b>0@5$2^6^5^4^3^2>0@4$c?4SEGS^7@4$9^7^6^3^4^2@5$2^8@2$8^7^3^6^5^4").
Proof.
  (* The whole record is a copy of [cs]'s except [kn], which [set_kn] replaces and the
     hypothesis supplies; [co_res] reads [model] alone, so the widening transports. *)
  intros;
  match goal with H : cs_ok _ _ _ _ _ |- _ => destruct H end;
  constructor;
    cbn [kn set_kn with_ss mk_ss s_log s_pc s_regs s_know s_next
         a_ss a_fd a_maps a_ylo a_tidset a_brk a_totsz a_eager a_abytes];
    try assumption; try reflexivity.
Qed.

