Lemma bump_sound : ltac2:(zQ "f0!ma!kud!hqa!io1!ho9!po2!oie!mvd!jt2!jv8!h9!jif!jle!rj5!ld>1E$e>2cs$1>1R@2$c@1$0#5@1$2@1$0#k0>4FULL>0@1$2@1$0#k0@1$3@1$2@1$0#8>5model$b>1m$8>3cs'$1>0@5$6^7^6^5^4^3>0@3$4@1$3$1@2$d^7^3@2$7$1^2@2$9@5$6^9^3^7^6^5@3$4$a@1$5^3@1$5^8").
Proof.
  (* bump_sound is not a bare rebuild: it concludes a CONJUNCTION and its cs' comes out of
     node_bump, so the record shape only appears after that match is resolved. *)
  intros E cs R FULL model m cs' Hco Hb.
  unfold node_bump in Hb.
  repeat match goal with
         | H : context[match ?x with _ => _ end] |- _ => destruct x eqn:?; try discriminate H
         end.
  injection Hb as <-.
  split.
  - destruct Hco; constructor;
      cbn [kn set_kn with_ss mk_ss s_log s_pc s_regs s_know s_next
           a_ss a_fd a_maps a_ylo a_tidset a_brk a_totsz a_eager a_abytes];
      try assumption; try reflexivity.
  - cbn [pc a_ss s_pc]; reflexivity.
Qed.

